import React, { useEffect, useState } from 'react';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { scykRoutes } from '../../config/scykRoutes';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import { createDailyIncidentReport } from '../../store/slices/dailyIncidentReportsSlice';
import { addToast } from '../../store/slices/uiSlice';
import { useFormOptions } from '../../hooks/useFormOptions';
import type { DailyIncidentReport } from '../../models/DailyIncidentReport';
import { ValidationErrors, ValidationRule, runValidation, scrollToFirstErrorSection, clearFieldErrors } from '../../utils/formValidation';
import styles from './DailyIncidentReportFormPage.module.css';
import { Button, Input, Select } from '@linm-soft-org/linm-web-common-components';

// ─── Validation rules ──────────────────────────────────────────────────────
const RULES: ValidationRule<Partial<DailyIncidentReport>>[] = [
  {
    field:     'reportedDate',
    sectionId: 'section-date',
    validate:  (f) => !f.reportedDate ? 'Ngày báo cáo là bắt buộc' : null,
  },
  {
    field:     'departmentId',
    sectionId: 'section-department',
    validate:  (f) => !f.departmentId ? 'Khoa, phòng là bắt buộc' : null,
  },
  {
    field:     'gmail',
    sectionId: 'section-gmail',
    validate:  (f) => {
      // Optional — only validate format when a value is entered
      if (f.gmail?.trim() && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.gmail.trim()))
        return 'Gmail không hợp lệ';
      return null;
    },
  },
];

const DailyIncidentReportFormPage: React.FC = () => {
  const appNavigate = useAppNavigate();
  const dispatch  = useAppDispatch();
  const { saving } = useAppSelector((s) => s.dailyIncidentReports);
  const authUser  = useAppSelector((s) => s.auth.user);

  const { departmentOptions, defaultDepartmentId } = useFormOptions('incident-list');

  const todayIso = new Date().toLocaleDateString('en-CA'); // YYYY-MM-DD in local TZ

  const [form, setForm] = useState<Partial<DailyIncidentReport>>(() => ({
    reportedDate:   todayIso,
    departmentId:   '',
    departmentName: '',
    hasIncident:    false,
    incidentCount:  0,
    gmail:          authUser?.email ?? '',
  }));

  const [validationErrors, setValidationErrors] = useState<ValidationErrors>({});
  const [submitted, setSubmitted] = useState<{ hasIncident: boolean } | null>(null);

  // Auto-fill khoa từ auth profile hoặc JWT defaultDepartmentId (init-data)
  useEffect(() => {
    const deptId = authUser?.departmentId || defaultDepartmentId;
    if (!deptId || departmentOptions.length === 0) return;
    const match = departmentOptions.find((d) => String(d.value) === deptId);
    setForm((prev) => {
      if (prev.departmentId && prev.departmentId !== deptId) return prev;
      const departmentName = match?.label
        ? String(match.label)
        : (authUser?.departmentName ?? prev.departmentName ?? '');
      if (prev.departmentId === deptId && prev.departmentName === departmentName) return prev;
      return { ...prev, departmentId: deptId, departmentName };
    });
  }, [authUser?.departmentId, authUser?.departmentName, defaultDepartmentId, departmentOptions]);

  const patch = (p: Partial<DailyIncidentReport>) => {
    setForm((prev) => ({ ...prev, ...p }));
    setValidationErrors((prev) => clearFieldErrors(prev, Object.keys(p)));
  };

  const handleDepartmentChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const val  = e.target.value;
    const dept = departmentOptions.find((d) => String(d.value) === val);
    patch({ departmentId: val, departmentName: dept?.label ?? '' });
  };

  const handleHasIncidentToggle = (value: boolean) => {
    patch({ hasIncident: value, incidentCount: value ? form.incidentCount ?? 0 : 0 });
  };

  const handleSubmit = async () => {
    const errors = runValidation(form, RULES);
    if (Object.keys(errors).length > 0) {
      setValidationErrors(errors);
      scrollToFirstErrorSection(errors, RULES);
      return;
    }

    const payload = {
      reportedDate:   form.reportedDate!,
      departmentId:   form.departmentId!,
      departmentName: form.departmentName ?? '',
      hasIncident:    form.hasIncident ?? false,
      incidentCount:  form.hasIncident ? (form.incidentCount ?? 0) : 0,
      gmail:          (form.gmail ?? '').trim(),
    };

    const resultAction = await dispatch(createDailyIncidentReport(payload as any));
    if (createDailyIncidentReport.fulfilled.match(resultAction)) {
      dispatch(addToast({ type: 'success', message: 'Báo cáo hằng ngày đã được gửi thành công!' }));
      setSubmitted({ hasIncident: payload.hasIncident });
    } else {
      dispatch(addToast({ type: 'error', message: 'Gửi báo cáo thất bại. Vui lòng thử lại.' }));
    }
  };

  // ── Success view ──────────────────────────────────────────────────────────
  if (submitted) {
    return (
      <div className={styles.page}>
        <div className={styles.header}>
          <div className={styles.titleGroup}>
            <button className={styles.backBtn} onClick={() => appNavigate(scykRoutes.dailyReports.list)}>
              <i className="fas fa-arrow-left" />
            </button>
            <h1 className={styles.title}>BC Hàng Ngày Form</h1>
          </div>
        </div>
        <div className={styles.body}>
          <div className={styles.formCard} style={{ textAlign: 'center', padding: '48px 32px' }}>
            <div style={{ fontSize: '3rem', marginBottom: '16px', color: '#16a34a' }}>
              <i className="fas fa-check-circle" />
            </div>
            <h2 style={{ margin: '0 0 8px', color: '#111827', fontSize: '1.25rem', fontWeight: 600 }}>
              Gửi báo cáo thành công!
            </h2>
            <p style={{ margin: '0 0 32px', color: '#6b7280', fontSize: '0.9rem' }}>
              Báo cáo hằng ngày đã được ghi nhận.
            </p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', alignItems: 'center' }}>
              {submitted.hasIncident && (
                <Button variant="primary" onClick={() => appNavigate(scykRoutes.incidents.new)}>
                  <i className="fas fa-plus-circle" /> Tạo Báo cáo sự cố mới
                </Button>
              )}
              <Button variant="secondary" onClick={() => appNavigate(scykRoutes.dailyReports.list)}>
                <i className="fas fa-list" /> Về danh sách
              </Button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.page}>
      {/* Header */}
      <div className={styles.header}>
        <div className={styles.titleGroup}>
          <button className={styles.backBtn} onClick={() => appNavigate(scykRoutes.dailyReports.list)}>
            <i className="fas fa-arrow-left" />
          </button>
          <h1 className={styles.title}>BC Hàng Ngày Form</h1>
        </div>
        <div className={styles.actions}>
          <Button variant="secondary" onClick={() => appNavigate(scykRoutes.dailyReports.list)}>
            Hủy
          </Button>
          <Button variant="primary" onClick={handleSubmit} disabled={saving}>
            {saving ? 'Đang gửi...' : 'Gửi Báo Cáo'}
          </Button>
        </div>
      </div>

      {/* Form body */}
      <div className={styles.body}>
        <div className={styles.formCard}>
          {/* Ngày báo cáo */}
          <div id="section-date" className={styles.field}>
            <label className={styles.label}>
              Ngày báo cáo <span className={styles.required}>*</span>
            </label>
            <Input
              type="date"
              value={form.reportedDate ?? ''}
              onChange={(e) => patch({ reportedDate: e.target.value })}
              error={validationErrors['reportedDate']}
            />
          </div>

          {/* Khoa, phòng */}
          <div id="section-department" className={styles.field}>
            <label className={styles.label}>
              Khoa, phòng <span className={styles.required}>*</span>
            </label>
            <Select
              value={form.departmentId ?? ''}
              onChange={handleDepartmentChange}
              options={departmentOptions}
              placeholder="-- Chọn khoa, phòng --"
              error={validationErrors['departmentId']}
            />
          </div>

          {/* Trong ngày có Sự cố hay không? */}
          <div className={styles.field}>
            <label className={styles.label}>
              Trong ngày có Sự cố hay không? <span className={styles.required}>*</span>
            </label>
            <div className={styles.toggleGroup}>
              <button
                type="button"
                className={`${styles.toggleBtn} ${form.hasIncident === true ? styles.toggleActive : ''}`}
                onClick={() => handleHasIncidentToggle(true)}
              >
                Có
              </button>
              <button
                type="button"
                className={`${styles.toggleBtn} ${form.hasIncident === false ? styles.toggleActive : ''}`}
                onClick={() => handleHasIncidentToggle(false)}
              >
                Không
              </button>
            </div>
          </div>

          {/* Số lượng sự cố — only shown when hasIncident = true */}
          {form.hasIncident && (
            <div className={styles.field}>
              <label className={styles.label}>Số lượng sự cố</label>
              <Input
                type="number"
                min={1}
                value={String(form.incidentCount ?? 0)}
                onChange={(e) => patch({ incidentCount: Math.max(0, parseInt(e.target.value) || 0) })}
              />
            </div>
          )}

          {/* Gmail */}
          <div id="section-gmail" className={styles.field}>
            <label className={styles.label}>Gmail</label>
            <Input
              type="email"
              placeholder="qlsc.ubna@gmail.com"
              value={form.gmail ?? ''}
              onChange={(e) => patch({ gmail: e.target.value })}
              error={validationErrors['gmail']}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default DailyIncidentReportFormPage;
